const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/interop";
const dep = "/w/node_modules/esmodule-false-dep";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.mkdirSync(dep, { recursive: true });
fs.writeFileSync(path.join(dep, "package.json"), JSON.stringify({ name: "esmodule-false-dep", version: "1.0.0", type: "commonjs", main: "index.js" }));
// A CommonJS dependency that sets __esModule to a falsy value
fs.writeFileSync(path.join(dep, "index.js"), "exports.__esModule = false\nexports.test = 'hello'\n");
fs.writeFileSync(path.join(dir, "package.json"), JSON.stringify({ name: "interop", private: true, type: "module" }));
fs.writeFileSync(path.join(dir, "interop.test.js"), [
  "import { test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "import * as ns from 'esmodule-false-dep'",
  "test('interop', () => {",
  "  writeFileSync(new URL('./result.json', import.meta.url), JSON.stringify({ keys: Object.keys(ns), test: ns.test, defaultTest: ns.default && ns.default.test }))",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const resultFile = path.join(dir, "result.json");
if (!fs.existsSync(resultFile)) {
  console.error("ERROR: the test file did not run (exit " + r.status + ")");
  process.exit(2);
}
const res = JSON.parse(fs.readFileSync(resultFile, "utf8"));
console.log("namespace keys: " + JSON.stringify(res.keys));
if (res.test !== "hello" || res.defaultTest !== "hello") {
  console.error("ERROR: unexpected import result " + JSON.stringify(res));
  process.exit(2);
}
if (res.keys.includes("default")) {
  console.log("PASS: CommonJS dependency with falsy __esModule (false) gets no ESM interop; import * namespace has a default key holding module.exports");
  process.exit(0);
}
if (res.keys.includes("__esModule") && res.keys.includes("test")) {
  console.error("FAIL: CommonJS dependency with falsy __esModule (false) still got ESM interop; import * namespace has no default key holding module.exports");
  process.exit(1);
}
console.error("ERROR: unexpected namespace keys " + JSON.stringify(res.keys));
process.exit(2);

